// ?validateArmorAndDamageFX@ActiveBody@@IBEXXZ
// partial score=0.78 date=2026-09-16
// BFME retail ActiveBody layout and armor-set refresh.
//
// The same operation is inlined in ActiveBody's constructor at 0x00211C42:
// walk the Object template's override chain, select the best armor set, then
// copy its armor and DamageFX pointers into ActiveBody.  That independent copy
// identifies the out-of-line body at 0x0020E9A0.

template<int N>
class BitFlags
{
public:
	unsigned int m_bits[(N + 31) / 32];
};

typedef BitFlags<11> ArmorSetFlags;

class Overridable
{
public:
	const Overridable *getFinalOverride() const
	{
		return m_nextOverride ? m_nextOverride->getFinalOverride() : this;
	}

	void *m_vtable;
	const Overridable *m_nextOverride;
};

class ArmorTemplateSet
{
public:
	unsigned int m_conditions;
	const void *m_armorTemplate;
	const void *m_damageFX;
};

class BfmeActiveBodyThingTemplate : public Overridable
{
public:
	const ArmorTemplateSet *findArmorTemplateSet(const ArmorSetFlags &flags) const;
};

template<class T>
class OverridePointer
{
public:
	const T *operator*() const
	{
		const T *result;
		if (!m_overridable)
			result = 0;
		else
			result = static_cast<const T *>(m_overridable->getFinalOverride());
		return result;
	}

	operator const T *() const { return operator*(); }

private:
	const T *m_overridable;
};

class Object
{
public:
	const BfmeActiveBodyThingTemplate *getTemplate() const
	{
		return m_template;
	}

	void *m_vtable;
	OverridePointer<BfmeActiveBodyThingTemplate> m_template;
};

class ActiveBody
{
protected:
	void validateArmorAndDamageFX() const;

private:
	char m_unreconstructed_00[8];
	const Object *m_object;
	char m_unreconstructed_0C[0xD0 - 0x0C];
	ArmorSetFlags m_curArmorSetFlags;
	mutable const ArmorTemplateSet *m_curArmorSet;
	mutable const void *m_curArmor;
	mutable const void *m_curDamageFX;
};

#pragma comment(linker, "/alternatename:?getFinalOverride@Overridable@@QBEPBV1@XZ=?j_000022bb@@YAXXZ")
#pragma comment(linker, "/alternatename:?findArmorTemplateSet@BfmeActiveBodyThingTemplate@@QBEPBVArmorTemplateSet@@ABV?$BitFlags@$0L@@@@Z=?j_0003ba89@@YAXXZ")

void ActiveBody::validateArmorAndDamageFX() const
{
	const BfmeActiveBodyThingTemplate *thingTemplate = m_object->getTemplate();
	const ArmorTemplateSet *set =
		thingTemplate->findArmorTemplateSet(m_curArmorSetFlags);
	if (set && set != m_curArmorSet)
	{
		m_curArmor = set->m_armorTemplate;
		m_curDamageFX = set->m_damageFX;
		m_curArmorSet = set;
	}
}
